import sys, json, pathlib, traceback, requests
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot, EpisodeOver
import numpy as np
from PIL import Image

r=Robot()
root=pathlib.Path('/app/runs')
(root/'spec.json').write_text(json.dumps(r.spec(),indent=2))
print('READY',flush=True)
n=0

def save(res):
    global n
    p=root/f'{n:03d}'
    n+=1
    res.save(str(p))
    for cam, im in res.last.items():
        Image.fromarray(im).save(p/f'{cam}.png')
    print(json.dumps({'dir':str(p),'meta':res.meta}),flush=True)

save(r.get_obs(depth=True))
for line in sys.stdin:
    try:
        a=json.loads(line)
        op=a.pop('op')
        if op=='obs': save(r.get_obs(**a))
        elif op=='submit': save(r.submit(**a))
        elif op=='ik': print(json.dumps(r.ik(**a)),flush=True)
        elif op=='fk': print(json.dumps(r.fk(**a)),flush=True)
        elif op=='status': print(json.dumps(r.status()),flush=True)
    except EpisodeOver as e:
        print('EPISODE_OVER',str(e),flush=True)
        print(json.dumps(r.status()),flush=True)
    except requests.exceptions.RequestException:
        traceback.print_exc()
        print('RECOVERED',json.dumps(r.wait_ready()),flush=True)
    except Exception:
        traceback.print_exc()
